ST.xhtml:p:
RTrigger1(CLK := bLoadCylinder1);
RTrigger2(CLK := bLoadCylinder2);
RTrigger3(CLK := bLoadCylinder3);
RTrigger4(CLK := bLoadCylinderUp1);
RTrigger5(CLK := bLoadCylinderUp2);
RTrigger6(CLK := bLoadCylinderUp3);
RTrigger7(CLK := bClaw);
RTrigger8(CLK := bSupportCylinder1);
RTrigger9(CLK := bSupportCylinder2);
RTrigger10(CLK := bSupportCylinder3);
RTrigger11(CLK := bSupportCylinder4);
RTrigger12(CLK := g_biQRManualLoad3);
FTrigger1(CLK := g_biQRManualLoad3);

IF RTrigger1.Q THEN
  IF bControlEnable THEN
    g_boLoadCylinder1 := TRUE;
  ELSE
    g_boLoadCylinder1 := FALSE;
  END_IF;
END_IF;
IF RTrigger2.Q THEN
  IF bControlEnable THEN
    g_boLoadCylinder2 := TRUE;
  ELSE
    g_boLoadCylinder2 := FALSE;
  END_IF;
END_IF;
IF RTrigger3.Q THEN
  IF bControlEnable THEN
    g_boLoadCylinder3 := TRUE;
  ELSE
    g_boLoadCylinder3 := FALSE;
  END_IF;
END_IF;
IF RTrigger4.Q THEN
  IF bControlEnable THEN
    g_boLoadCylinder1Up := TRUE;
  ELSE
    g_boLoadCylinder1Up := FALSE;
  END_IF;
END_IF;
IF RTrigger5.Q THEN
  IF bControlEnable THEN
    g_boLoadCylinder2Up := TRUE;
  ELSE
    g_boLoadCylinder2Up := FALSE;
  END_IF;
END_IF;
IF RTrigger6.Q THEN
  IF bControlEnable THEN
    g_boLoadCylinder3Up := TRUE;
  ELSE
    g_boLoadCylinder3Up := FALSE;
  END_IF;
END_IF;
IF RTrigger12.Q THEN
  g_boLoadCylinder3Up := TRUE;
END_IF;
IF FTrigger1.Q THEN
  g_boLoadCylinder3Up := FALSE;
END_IF;

IF RTrigger7.Q THEN
  IF bControlEnable THEN
    g_boClawEnable := TRUE;
  ELSE
    g_boClawEnable := FALSE;
  END_IF;
END_IF;


IF RTrigger8.Q THEN
  IF bControlEnable THEN
    g_boSupportCylinder1 := TRUE;
  ELSE
    g_boSupportCylinder1 := FALSE;
  END_IF;
END_IF;
IF RTrigger9.Q THEN
  IF bControlEnable THEN
    g_boSupportCylinder2 := TRUE;
  ELSE
    g_boSupportCylinder2 := FALSE;
  END_IF;
END_IF;
IF RTrigger10.Q THEN
  IF bControlEnable THEN
    g_boSupportCylinder3 := TRUE;
  ELSE
    g_boSupportCylinder3 := FALSE;
  END_IF;
END_IF;
IF RTrigger11.Q THEN
  IF bControlEnable THEN
    g_boSupportCylinder4 := TRUE;
  ELSE
    g_boSupportCylinder4 := FALSE;
  END_IF;
END_IF;

IF g_boLoadCylinder1 THEN
  bLoadCyl1State := TRUE;
ELSE 
  bLoadCyl1State := FALSE;
END_IF;

IF g_boLoadCylinder2 THEN
  bLoadCyl2State := TRUE;
ELSE 
  bLoadCyl2State := FALSE;
END_IF;

IF g_boLoadCylinder3 THEN
  bLoadCyl3State := TRUE;
ELSE 
  bLoadCyl3State := FALSE;
END_IF;

IF g_boLoadCylinder1Up THEN
  bLoadCylUp1State := TRUE;
ELSE
  bLoadCylUp1State := FALSE;
END_IF;

IF g_boLoadCylinder2Up THEN
  bLoadCylUp2State := TRUE;
ELSE
  bLoadCylUp2State := FALSE;
END_IF;

IF g_boLoadCylinder3Up THEN
  bLoadCylUp3State := TRUE;
ELSE
  bLoadCylUp3State := FALSE;
END_IF;


IF g_boClawEnable THEN
  bClawState := TRUE;
ELSE
  bClawState := FALSE;
END_IF;

IF g_bSupportInPlaceEnable THEN
  IF g_bSupport1UpInPlace THEN
    bSupportCyl1State := TRUE;
  END_IF;
  IF g_bSupport1DownInPlace THEN
    bSupportCyl1State := FALSE;
  END_IF;

  IF g_bSupport2UpInPlace THEN
    bSupportCyl2State := TRUE;
  END_IF;
  IF g_bSupport2DownInPlace THEN
    bSupportCyl2State := FALSE;
  END_IF;

  IF g_bSupport3UpInPlace THEN
    bSupportCyl3State := TRUE;
  END_IF;
  IF g_bSupport3DownInPlace THEN
    bSupportCyl3State := FALSE;
  END_IF;

  IF g_bSupport4UpInPlace THEN
    bSupportCyl4State := TRUE;
  END_IF;
  IF g_bSupport4DownInPlace THEN
    bSupportCyl4State := FALSE;
  END_IF;
ELSE
  IF g_boSupportCylinder1 THEN
    bSupportCyl1State := TRUE;
  ELSE
    bSupportCyl1State := FALSE;
  END_IF;

  IF g_boSupportCylinder2 THEN
    bSupportCyl2State := TRUE;
  ELSE
    bSupportCyl2State := FALSE;
  END_IF;

  IF g_boSupportCylinder3 THEN
    bSupportCyl3State := TRUE;
  ELSE
    bSupportCyl3State := FALSE;
  END_IF;

  IF g_boSupportCylinder4 THEN
    bSupportCyl4State := TRUE;
  ELSE
    bSupportCyl4State := FALSE;
  END_IF;
END_IF;
